    public sealed partial class NavigationPhysicalBodyTests
    {
        [TestCase(false)][TestCase(true)]
        public void BodyArrivalInputExactEightOwnersDistinctProviderRootsAndNextCompiler(bool independent)
        {
            var p0=(LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(4,new NavObstacle[0],1));var p1=(LayeredNavigationProvider)NavigationAdmission.CertifiedFlatProvider(new NavGeometry(4,new NavObstacle[0],1));var c=new NavClearanceProfile("ground",1,"ground",1,.25);var profile=new NavGraphProfile(new string('c',64),"distance",1,1);var limits=new NavGraphCompileLimits(2000,2000,10000);var arrival=new NavigationProfile();
            NavArrivalMember Member(int entity,int order)=>new NavArrivalMember(entity,1,order,1,new NavLocation(new NavPoint(-2+order*.25,0),NavLocation.FlatSurface),c,3,1,1,1,0,1,1,1,"HOLD");var source=new NavArrivalCandidateSource("source",1,new NavLocation(new NavPoint(1,0),NavLocation.FlatSurface),new[]{new NavLocation(new NavPoint(1,0),NavLocation.FlatSurface),new NavLocation(new NavPoint(1,1),NavLocation.FlatSurface)});var occupancy=new NavArrivalOccupancySnapshot(3,new NavArrivalOccupant[0]);var original=new NavArrivalInput("topology","profile",p0,profile,arrival,limits,source,new[]{Member(5,2),Member(3,1)},occupancy,4096,new[]{new NavArrivalWorkingBinding(5,p1,profile),new NavArrivalWorkingBinding(3,p0,profile)},independent);
            var hot=new NavigationRetentionBudget();Assert.True(hot.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var birth));var r=birth.OwnedReservation();var provider0=LayeredNavigationProvider.CopyOwned(p0,r);var provider1=LayeredNavigationProvider.CopyOwned(p1,r);var meta=NavGraphMetadata.CopyOptionalUnowned(c,profile,limits,r);var ownedArrival=NavigationProfile.CopyOwned(arrival,r);var ownedSource=NavArrivalCandidateSource.CopyOwned(source,r);var ownedOccupancy=NavArrivalOccupancySnapshot.CopyOwned(occupancy,new NavArrivalOccupant[0],r);var members=new[]{NavArrivalMember.CopyOwned(original.Members[0],meta.Clearance,r),NavArrivalMember.CopyOwned(original.Members[1],meta.Clearance,r)};var bindings=new[]{NavArrivalWorkingBinding.CreateOwned(3,provider0,meta.Profile,r),NavArrivalWorkingBinding.CreateOwned(5,provider1,meta.Profile,r)};
            var changedArrival=new NavigationProfile(NavigationProfile.DefaultProfileId,1,.72,4,4.5,.8,.15,3.6,.08,57);var oldDigestBlind=new NavArrivalInput(original.TopologyIdentity,original.ProfileIdentity,p0,profile,changedArrival,limits,source,original.Members,occupancy,4096,original.WorkingBindings,independent);Assert.AreEqual(original.StableKey,oldDigestBlind.StableKey);var wrongOwnedArrival=NavigationProfile.CopyOwned(changedArrival,r);var refusedProfile=new Refusal(birth,int.MaxValue);Assert.Throws<ArgumentException>(()=>NavArrivalInput.CopyOwned(original,provider0,meta.Profile,wrongOwnedArrival,meta.Limits,ownedSource,members,ownedOccupancy,bindings,refusedProfile));Assert.Zero(refusedProfile.Calls);wrongOwnedArrival.StorageRoot.ReleaseOwner();wrongOwnedArrival=null;oldDigestBlind=null;
            var value=NavArrivalInput.CopyOwned(original,provider0,meta.Profile,ownedArrival,meta.Limits,ownedSource,members,ownedOccupancy,bindings,r);Assert.AreEqual(original.StableKey,value.StableKey);Assert.AreNotSame(original.StableKey,value.StableKey);Assert.AreNotSame(original.TopologyIdentity,value.TopologyIdentity);Assert.AreSame(provider0.Binding,value.ProviderIdentity);
            provider0.StorageRoot.ReleaseOwner();provider1.StorageRoot.ReleaseOwner();meta.Release();ownedArrival.StorageRoot.ReleaseOwner();ownedSource.StorageRoot.ReleaseOwner();ownedOccupancy.StorageRoot.ReleaseOwner();foreach(var m in members)m.StorageRoot.ReleaseOwner();foreach(var b in bindings)b.StorageRoot.ReleaseOwner();birth.Attach(value.StorageRoot);birth.Commit(value.StorageRoot,_=>{});byte[] bytes=CaptureGraph(hot,value.StorageRoot);long charge=Unique(value.StorageRoot);Assert.AreEqual(charge,hot.PhysicalBytes);
            byte[] Next(NavigationRetentionBudget budget,NavArrivalInput input,int member,out long physical){Assert.True(budget.TryOpenScope(NavigationPreparationKind.Solve,1,100+member,out var operation));var m=input.Members[member];var b=input.WorkingFor(m);var work=LayeredNavigationCompileWork.CreateOwned(b.Provider,m.Clearance,b.Profile,input.Limits,operation.OwnedReservation());work.Advance(1);work.SealPrepared();operation.Attach(work);operation.Commit(work,_=>{});var output=CaptureGraph(budget,work);physical=Unique(work);work.ReleaseOwner();return output;}
            byte[] expected0=Next(hot,value,0,out long next0),expected1=Next(hot,value,1,out long next1);CollectionAssert.AreEqual(bytes,CaptureGraph(hot,value.StorageRoot));value.StorageRoot.ReleaseOwner();value=null;original=null;p0=null;p1=null;provider0=null;provider1=null;meta=null;ownedArrival=null;ownedSource=null;ownedOccupancy=null;members=null;bindings=null;source=null;occupancy=null;Assert.Zero(hot.PhysicalBytes);Assert.Zero(hot.HeldBytes);
            var cold=new NavigationRetentionBudget();Assert.True(cold.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var decode));var restored=(NavDeclarationStorage)Decode(bytes,decode.OwnedReservation());decode.Attach(restored);decode.Commit(restored,_=>{});var a=(NavArrivalInput)restored.Facade;Assert.AreEqual(independent,a.IndependentMembers);Assert.AreEqual(2,a.Members.Count);Assert.AreEqual(3,a.Members[0].EntityId);Assert.AreEqual(5,a.Members[1].EntityId);Assert.AreSame(restored.Second,restored.Third);Assert.AreSame(a.Profile.MetadataOwner,a.Members[0].Clearance.MetadataOwner);Assert.AreSame(a.Members[0].Clearance,a.Members[1].Clearance);Assert.AreSame(a.Provider,a.WorkingBindings[0].Provider);Assert.AreNotSame(a.WorkingBindings[0].Provider,a.WorkingBindings[1].Provider);Assert.AreEqual(a.WorkingBindings[0].Provider.Binding,a.WorkingBindings[1].Provider.Binding);Assert.AreSame(a.Profile,a.WorkingBindings[0].Profile);Assert.AreSame(a.Profile,a.WorkingBindings[1].Profile);Assert.AreSame(((INavStorageFacade)a.Provider).StorageRoot,restored.First);Assert.AreSame(a.ArrivalProfile.StorageRoot,restored.Fourth);Assert.AreSame(a.Source.StorageRoot,restored.Fifth);Assert.AreSame(a.Occupancy.StorageRoot,restored.Sixth);var views=(NavRetainedArray<NavOwnedStorage>)restored.Seventh;var priv=(NavRetainedArray<NavArrivalMember>)views[0];var pub=(NavRetainedArray<NavArrivalMember>)views[1];Assert.AreNotSame(priv,pub);Assert.AreNotSame(priv.ReadOnlyBacking,pub.ReadOnlyBacking);for(int n=0;n<2;n++)Assert.AreSame(priv[n],pub[n]);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));Assert.AreEqual(charge,cold.PhysicalBytes);CollectionAssert.AreEqual(expected0,Next(cold,a,0,out long actual0));CollectionAssert.AreEqual(expected1,Next(cold,a,1,out long actual1));Assert.AreEqual(next0,actual0);Assert.AreEqual(next1,actual1);
            NavArrivalInput Born(INavStorageReservation reservation)=>NavArrivalInput.CopyOwned(a,a.Provider,a.Profile,a.ArrivalProfile,a.Limits,a.Source,a.Members,a.Occupancy,a.WorkingBindings,reservation);Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20,out var trialBirth));var counter=new Refusal(trialBirth,int.MaxValue);var copied=Born(counter);trialBirth.Attach(copied.StorageRoot);int calls=counter.Calls;trialBirth.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);for(int nth=1;nth<=calls;nth++){Assert.True(cold.TryOpenScope(NavigationPreparationKind.Admission,1,20+nth,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Born(refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.AreEqual(charge,cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);CollectionAssert.AreEqual(bytes,CaptureGraph(cold,restored));}
            var foreign=new NavigationRetentionBudget();Assert.True(foreign.TryOpenScope(NavigationPreparationKind.Admission,1,1,out var rejected));Assert.Throws<ArgumentException>(()=>Born(rejected.OwnedReservation()));Assert.Zero(foreign.PhysicalBytes);Assert.AreEqual(NavigationRetentionBudget.ScopeBytes,foreign.HeldBytes);rejected.Discard();restored.Release();restored=null;a=null;priv=null;pub=null;views=null;Assert.Zero(cold.PhysicalBytes);Assert.Zero(cold.HeldBytes);
            var counted=new NavigationRetentionBudget();Assert.True(counted.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var scope));var all=new Refusal(scope,int.MaxValue);var trial=Decode(bytes,all);scope.Attach(trial);int allocations=all.Calls;scope.Discard();Assert.Zero(counted.PhysicalBytes);for(int nth=1;nth<=allocations;nth++){var bad=new NavigationRetentionBudget();Assert.True(bad.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var rejection));var refusal=new Refusal(rejection,nth);Assert.Throws<InvalidOperationException>(()=>Decode(bytes,refusal));Assert.AreEqual(nth,refusal.Calls);rejection.Discard();Assert.Zero(bad.PhysicalBytes);Assert.Zero(bad.HeldBytes);Assert.Zero(bad.ActiveScopes);}
            byte[] malformed=(byte[])bytes.Clone();malformed[malformed.Length-2]=255;malformed[malformed.Length-1]=255;var corrupt=new NavigationRetentionBudget();Assert.True(corrupt.TryOpenScope(NavigationPreparationKind.Decode,1,1,out var corruptScope));Assert.Throws<ArgumentException>(()=>Decode(malformed,corruptScope.OwnedReservation()));corruptScope.Discard();Assert.Zero(corrupt.PhysicalBytes);Assert.Zero(corrupt.HeldBytes);
        }
